{
  "doneWhen": "Crown crafted (inventory contains Crown) and player is adjacent to the workbench",
  "modes": [
    {
      "name": "collect-and-craft",
      "when": "always",
      "macro": "skill",
      "params": { "name": "field-work" }
    }
  ],
  "skills": [
    {
      "name": "field-work",
      "skill": "async (b) => {
  const need = { Wood: 3, Stone: 2 };
  const have = { Wood: 0, Stone: 0 };
  const inv = await b.items();
  for (const it of inv) {
    if (it.name === 'Wood') have.Wood += it.stack;
    if (it.name === 'Stone') have.Stone += it.stack;
  }
  const targets = [
    { name: 'Wood', x: 6, y: 7 },
    { name: 'Wood', x: 10, y: 3 },
    { name: 'Wood', x: 10, y: 1 },
    { name: 'Stone', x: 10, y: 7 },
    { name: 'Stone', x: 11, y: 8 }
  ];
  for (const t of targets) {
    if (have[t.name] >= need[t.name]) continue;
    const r = await b.walkTo(t.x, t.y, 'adjacent');
    if (!r.ok) { b.log('walk fail ' + t.name + ' ' + r.reason); continue; }
    const p = await b.faceAndPress(t.x, t.y, 'KeyE');
    if (p && p.ok) have[t.name] += 1;
    else b.log('pick fail ' + t.name);
  }
  if (have.Wood < 3 || have.Stone < 2) {
    b.log('missing materials ' + JSON.stringify(have));
    return;
  }
  const w = await b.walkTo(6, 2, 'adjacent');
  if (!w.ok) { b.log('bench walk fail ' + w.reason); return; }
  const c = await b.faceAndPress(6, 2, 'KeyC');
  b.log('craft ' + JSON.stringify(c));
}",
      "check": "async (b) => {
  const inv = await b.items();
  const hasCrown = inv.some(i => i.name === 'Crown');
  const body = await b.body();
  const nearBench = Math.abs(body.x - 6) + Math.abs(body.y - 2) === 1;
  return { ok: hasCrown && nearBench, detail: 'crown=' + hasCrown + ' nearBench=' + nearBench };
}"
    }
  ]
}
